// The knowledge eval fixtures: six files under tests/fixtures/knowledge/,
// GENERATED by this file, never hand-written binaries. Three PDFs are built byte by
// byte here (correct xref tables, so the real pdf.js reads them), the three office
// files come from the app's own builders (buildOffice), exactly as a user's files
// would arrive. Run `MKMN_GENERATE_FIXTURES=1 pnpm exec vitest run
// tests/knowledge-fixtures.test.ts` to (re)write them; the outputs are committed and
// the verification tests below always run against the committed bytes.
// The Arabic PDF stores each word as its own text operation, the word's characters
// reversed: pdf.js's text layer bidi-reverses every right-to-left item, so this
// comes back as logical Arabic words in logical order (digits and Latin words are
// stored as they are and are not touched).
import { describe, expect, it } from "vitest";
import { extractPdfText } from "../src/core/pdf";
import { readOffice } from "../src/core/office";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { join } from "node:path";

const FIXTURE_DIR = join(fileURLToPath(new URL(".", import.meta.url)), "fixtures", "knowledge");
const GENERATE = process.env.MKMN_GENERATE_FIXTURES === "1";

// ------------------------------------------------------------------ pdf building

/** A binary-safe PDF writer: the parts are ASCII strings or raw bytes, the xref table is exact. */
function buildPdf(parts: (string | Uint8Array)[]): Uint8Array {
  const chunks: Uint8Array[] = [];
  let len = 0;
  const push = (c: Uint8Array) => { chunks.push(c); len += c.length; };
  const ascii = (s: string) => { const b = new Uint8Array(s.length); for (let i = 0; i < s.length; i++) b[i] = s.charCodeAt(i) & 0xff; push(b); };
  ascii("%PDF-1.4\n");
  const offsets: number[] = [];
  parts.forEach((part, i) => {
    offsets.push(len);
    ascii(`${i + 1} 0 obj\n`);
    if (typeof part === "string") ascii(part);
    else push(part);
    ascii("\nendobj\n");
  });
  const xrefAt = len;
  ascii(`xref\n0 ${parts.length + 1}\n0000000000 65535 f \n`);
  for (const off of offsets) ascii(`${String(off).padStart(10, "0")} 00000 n \n`);
  ascii(`trailer\n<</Size ${parts.length + 1}/Root 1 0 R>>\nstartxref\n${xrefAt}\n%%EOF\n`);
  const out = new Uint8Array(len);
  let at = 0;
  for (const c of chunks) { out.set(c, at); at += c.length; }
  return out;
}

const utf16beHex = (s: string): string => [...s].map((ch) => ch.codePointAt(0)!.toString(16).padStart(4, "0")).join("");
const flip = (s: string): string => [...s].reverse().join("");
const HAS_ARABIC = /[\u0600-\u06FF]/;

/** An English (or any Latin) PDF: one Helvetica font shared by every page; each line of a page sits on its own baseline. */
function latinPdf(pages: string[][]): Uint8Array {
  const parts: (string | Uint8Array)[] = [];
  parts.push("<</Type/Catalog/Pages 2 0 R>>");
  parts.push(`<</Type/Pages/Kids[${pages.map((_, p) => `${4 + p * 2} 0 R`).join(" ")}]/Count ${pages.length}>>`);
  parts.push("<</Type/Font/Subtype/Type1/BaseFont/Helvetica>>");
  pages.forEach((lines, p) => {
    const base = 4 + p * 2;
    parts.push(`<</Type/Page/Parent 2 0 R/MediaBox[0 0 540 300]/Contents ${base + 1} 0 R/Resources<</Font<</F1 3 0 R>>>>>>`);
    const body = lines.map((line, li) => `BT /F1 12 Tf 30 ${250 - li * 24} Td (${line.replace(/([()\\])/g, "\\$1")}) Tj ET`).join("\n");
    parts.push(`<</Length ${body.length}>>\nstream\n${body}\nendstream`);
  });
  return buildPdf(parts);
}

/** An Arabic PDF: a Type0 font with Identity-H codes and a ToUnicode map (the codes are the code points). */
function arabicPdf(pages: string[][]): Uint8Array {
  const parts: (string | Uint8Array)[] = [];
  parts.push("<</Type/Catalog/Pages 2 0 R>>");
  parts.push(`<</Type/Pages/Kids[${pages.map((_, p) => `${7 + p * 2} 0 R`).join(" ")}]/Count ${pages.length}>>`);
  parts.push(`<</Type/Font/Subtype/Type0/BaseFont/CedarArabic/Encoding/Identity-H/DescendantFonts[4 0 R]/ToUnicode 5 0 R>>`);
  parts.push(`<</Type/Font/Subtype/CIDFontType2/BaseFont/CedarArabic/CIDSystemInfo<</Registry (Adobe)/Ordering (UCS)/Supplement 0>>/FontDescriptor 6 0 R/DW 600>>`);
  const chars = [...new Set(pages.flat().join(""))].sort();
  let cmap = "/CIDInit /ProcSet findresource begin\n12 dict begin\nbegincmap\n/CIDSystemInfo <</Registry (Adobe)/Ordering (UCS)/Supplement 0>> def\n/CMapName /Adobe-Identity-UCS def\n/CMapType 2 def\n1 begincodespacerange\n<0000> <FFFF>\nendcodespacerange\n";
  for (let i = 0; i < chars.length; i += 100) {
    const chunk = chars.slice(i, i + 100);
    cmap += `${chunk.length} beginbfchar\n${chunk.map((c) => `<${utf16beHex(c)}> <${utf16beHex(c)}>`).join("\n")}\nendbfchar\n`;
  }
  cmap += "endcmap\nCMapName currentdict /CMap defineresource pop\nend\nend";
  parts.push(`<</Length ${cmap.length}>>\nstream\n${cmap}\nendstream`);
  parts.push(`<</Type/FontDescriptor/FontName/CedarArabic/Flags 4/FontBBox[0 -200 1000 900]/ItalicAngle 0/Ascent 800/Descent -200/CapHeight 700/StemV 80>>`);
  pages.forEach((lines, p) => {
    const base = 7 + p * 2;
    parts.push(`<</Type/Page/Parent 2 0 R/MediaBox[0 0 540 300]/Contents ${base + 1} 0 R/Resources<</Font<</F1 3 0 R>>>>>>`);
    // one text operation per word: each right-to-left item comes back from pdf.js's
    // text layer with its characters reversed, so Arabic words are stored reversed;
    // digits and Latin words are stored as they are
    const ops: string[] = [];
    lines.forEach((line, li) => {
      let x = 30;
      for (const w of line.split(/\s+/).filter(Boolean)) {
        const stored = HAS_ARABIC.test(w) ? flip(w) : w;
        ops.push(`BT /F1 14 Tf ${x} ${250 - li * 28} Td <${utf16beHex(stored)}> Tj ET`);
        x += w.length * 9 + 12;
      }
    });
    const body = ops.join("\n");
    parts.push(`<</Length ${body.length}>>\nstream\n${body}\nendstream`);
  });
  return buildPdf(parts);
}

/** A PDF with only a picture on every page (the scanned case): an uncompressed 8x8 RGB image, no text at all. */
function imageOnlyPdf(count: number): Uint8Array {
  const parts: (string | Uint8Array)[] = [];
  parts.push("<</Type/Catalog/Pages 2 0 R>>");
  parts.push(`<</Type/Pages/Kids[${Array.from({ length: count }, (_, p) => `${3 + p * 3} 0 R`).join(" ")}]/Count ${count}>>`);
  for (let p = 0; p < count; p++) {
    const base = 3 + p * 3;
    parts.push(`<</Type/Page/Parent 2 0 R/MediaBox[0 0 200 200]/Contents ${base + 1} 0 R/Resources<</XObject<</Im1 ${base + 2} 0 R>>>>>>`);
    parts.push(`<</Length 40>>\nstream\nq 200 0 0 200 0 0 cm /Im1 Do Q\nendstream`);
    const px = new Uint8Array(8 * 8 * 3);
    for (let i = 0; i < px.length; i += 3) { px[i] = (p * 37 + i) % 256; px[i + 1] = 90; px[i + 2] = 140; }
    const head = new TextEncoder().encode(`<</Type/XObject/Subtype/Image/Width 8/Height 8/ColorSpace/DeviceRGB/BitsPerComponent 8/Length ${px.length}>>\nstream\n`);
    const foot = new TextEncoder().encode("\nendstream");
    const one = new Uint8Array(head.length + px.length + foot.length);
    one.set(head);
    one.set(px, head.length);
    one.set(foot, head.length + px.length);
    parts.push(one);
  }
  return buildPdf(parts);
}

