// ------------------------------------------------------------------ generation (gated)

it("writes the fixture files (run with MKMN_GENERATE_FIXTURES=1)", { skip: GENERATE ? false : "generation mode only; the committed outputs are what the tests read" }, async () => {
  mkdirSync(FIXTURE_DIR, { recursive: true });
  const { buildOffice } = await import("../src/core/office");
  writeFileSync(join(FIXTURE_DIR, "handbook-en.pdf"), latinPdf(enPages));
  writeFileSync(join(FIXTURE_DIR, "dalil-ar.pdf"), arabicPdf(arPages));
  writeFileSync(join(FIXTURE_DIR, "scanned-notices.pdf"), imageOnlyPdf(scannedPages));
  writeFileSync(join(FIXTURE_DIR, "staff-handbook.docx"), await buildOffice("docx", DOCX_SRC));
  writeFileSync(join(FIXTURE_DIR, "equipment.xlsx"), await buildOffice("xlsx", XLSX_SRC));
  writeFileSync(join(FIXTURE_DIR, "renovation-plan.pptx"), await buildOffice("pptx", PPTX_SRC));
  writeFileSync(join(FIXTURE_DIR, "MANIFEST.json"), JSON.stringify({
    note: "Generated by tests/knowledge-fixtures.test.ts with MKMN_GENERATE_FIXTURES=1; never hand-edited. Fact pages are stable: the eval datasets name them.",
    files: [
      { file: "handbook-en.pdf", pages: 200, factsOnPages: Object.keys(EN_FACTS).map(Number) },
      { file: "dalil-ar.pdf", pages: arPages.length, factsOnPages: arPages.map((_, i) => i + 1) },
      { file: "scanned-notices.pdf", pages: scannedPages, text: "none (the OCR fixture)" },
      { file: "staff-handbook.docx" },
      { file: "equipment.xlsx", sheets: ["Equipment"] },
      { file: "renovation-plan.pptx", slides: 3 },
    ],
  }, null, 2));
  expect(true).toBe(true);
});

// ------------------------------------------------------------------ verification (always)

const pdfjsDoc = async (bytes: Uint8Array) => {
  const pdfjs = await import("pdfjs-dist/legacy/build/pdf.mjs");
  return pdfjs.getDocument({ data: bytes, useWorkerFetch: false, isEvalSupported: false }).promise;
};

/** A fixture file's bytes: pdf.js wants a true Uint8Array, not a Buffer view. */
const bytesOf = (name: string): Uint8Array => {
  const buf = readFileSync(join(FIXTURE_DIR, name));
  return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);
};

/** The text under one `[page N]` mark of an extracted PDF. */
const pageTextOf = (extracted: string, n: number): string => {
  const at = extracted.indexOf(`[page ${n}]`);
  if (at < 0) return "";
  const next = extracted.indexOf("\n[page ", at + 1);
  return extracted.slice(at, next < 0 ? undefined : next);
};

describe("knowledge fixtures (committed, generated)", () => {
  it("the English handbook: 200 pages, facts on their pages, chapter marks from headings", async () => {
    const bytes = bytesOf("handbook-en.pdf");
    const doc = await pdfjsDoc(bytes);
    expect(doc.numPages).toBe(200);
    const text = await extractPdfText(doc as never);
    expect(text).toContain("[page 200]");
    const p63 = pageTextOf(text, 63);
    expect(p63).toContain("[chapter: Chapter 9: Suppliers]");
    expect(p63).toContain("Northbridge Office Ltd, contract NB-2214");
    const p150 = pageTextOf(text, 150);
    expect(p150).toContain("maintenance reserve holds 21000 dinars");
    const p15 = pageTextOf(text, 15);
    expect(p15).toContain("Loans run for 21 days");
    // the fact pages do not leak into the filler: page 151 is filler
    expect(pageTextOf(text, 151)).toContain("H-151");
  });

  it("the Arabic guide: logical Arabic words on their pages", async () => {
    const bytes = bytesOf("dalil-ar.pdf");
    const doc = await pdfjsDoc(bytes);
    expect(doc.numPages).toBe(18);
    const text = await extractPdfText(doc as never);
    expect(pageTextOf(text, 3)).toContain("كريم أبيض");
    expect(pageTextOf(text, 3)).toContain("2018");
    expect(pageTextOf(text, 11)).toContain("رسوم الانخراط");
    expect(pageTextOf(text, 11)).toContain("20 دينارا");
    expect(pageTextOf(text, 17)).toContain("51234678");
    expect(pageTextOf(text, 18)).toContain("branch@cvl.org");
  });

  it("the scanned notices: no text on any page (the OCR fixture)", async () => {
    const bytes = bytesOf("scanned-notices.pdf");
    const doc = await pdfjsDoc(bytes);
    expect(doc.numPages).toBe(3);
    const text = await extractPdfText(doc as never);
    expect(text.trim()).toBe("");
  });

  it("the Word handbook, the workbook and the deck read back through the app's own readers", async () => {
    const docx = await readOffice("docx", readFileSync(join(FIXTURE_DIR, "staff-handbook.docx")));
    expect(docx).toContain("Rami Nassar, extension 204");
    expect(docx).toContain("## Emergency contacts");
    const xlsx = await readOffice("xlsx", readFileSync(join(FIXTURE_DIR, "equipment.xlsx")));
    expect(xlsx).toContain("## Equipment");
    expect(xlsx).toContain("| Projector | Main hall | 2 | 2022 | good |");
    expect(xlsx).toContain("| Desks | Reading room | 86 | 2018 | worn |");
    const pptx = await readOffice("pptx", readFileSync(join(FIXTURE_DIR, "renovation-plan.pptx")));
    expect(pptx).toContain("# Renovation Plan 2027");
    expect(pptx).toContain("The west wing closes in January 2027");
    expect(pptx).toContain("Notes: structural work first");
  });
});
